package org.slavicmyths.verify.client;
import java.nio.file.*;import java.util.*;
import net.minecraft.client.Minecraft;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.RenderShape;
/** Actual client baked registry/model/renderer checks, not visual approval of every model. */
final class Assets269 {
 static boolean done;static final List<Map<String,Object>> checks=new ArrayList<>();
 static void check(boolean ok,String test){checks.add(Map.of("status",ok?"PASS":"FAIL","test",test));}
 static void particle(net.minecraft.client.resources.model.BakedModel model,String id){particle(model,id,null);}
 static void particle(net.minecraft.client.resources.model.BakedModel model,String id,net.minecraft.world.level.block.state.BlockState state){var missing=net.minecraft.client.renderer.texture.MissingTextureAtlasSprite.getLocation();check(!model.getParticleIcon().contents().name().equals(missing),"native particle sprite stitched "+id);var faces=new ArrayList<String>();for(int i=-1;i<6;i++){var side=i<0?null:net.minecraft.core.Direction.values()[i];for(var quad:model.getQuads(state,side,net.minecraft.util.RandomSource.create(269),net.neoforged.neoforge.client.model.data.ModelData.EMPTY,null))if(quad.getSprite().contents().name().equals(missing))faces.add(String.valueOf(side));}check(faces.isEmpty(),"native baked face sprites stitched "+id+(faces.isEmpty()?"":" missing="+faces));}
 static void run(Minecraft mc){if(done)return;done=true;var out=new LinkedHashMap<String,Object>();int items=0,states=0,entities=0;var errors=new ArrayList<String>();try{
  var missing=mc.getModelManager().getMissingModel();
  for(var item:BuiltInRegistries.ITEM){var id=BuiltInRegistries.ITEM.getKey(item);if(!id.getNamespace().equals("slavicmyths"))continue;items++;var model=mc.getItemRenderer().getModel(new ItemStack(item),mc.level,mc.player,0);check(model!=null&&model!=missing,"native item baked model "+id);if(model!=null&&model!=missing)particle(model,id.toString());}
  for(var block:BuiltInRegistries.BLOCK){var id=BuiltInRegistries.BLOCK.getKey(block);if(!id.getNamespace().equals("slavicmyths"))continue;for(var state:block.getStateDefinition().getPossibleStates())if(state.getRenderShape()!=RenderShape.INVISIBLE){states++;var model=mc.getBlockRenderer().getBlockModel(state);check(model!=null&&model!=missing,"native block state baked model "+state);if(model!=null&&model!=missing)particle(model,state.toString(),state);}}
  for(var type:BuiltInRegistries.ENTITY_TYPE){var id=BuiltInRegistries.ENTITY_TYPE.getKey(type);if(!id.getNamespace().equals("slavicmyths"))continue;entities++;try{var entity=type.create(mc.level);check(entity!=null,"native client entity factory "+id);if(entity==null)continue;var renderer=mc.getEntityRenderDispatcher().getRenderer(entity);check(renderer!=null,"actual registered renderer "+id);if(renderer!=null){var texture=renderer.getTextureLocation(entity);check(texture!=null&&(texture.getPath().startsWith("textures/atlas/")||mc.getResourceManager().getResource(texture).isPresent()),"native renderer texture resolves "+id+" "+texture);}}catch(Throwable ex){errors.add(id+" "+ex);check(false,"native entity renderer initialization "+id);}}
 }catch(Throwable ex){errors.add(ex.toString());check(false,"client assets audit exception");}try{out.put("status",checks.stream().allMatch(x->x.get("status").equals("PASS"))?"PASS_CLIENT_REGISTRIES":"FAIL");out.put("items",items);out.put("model_block_states",states);out.put("entity_types",entities);out.put("checks",checks);out.put("errors",errors);out.put("master_volume",mc.options.getSoundSourceOptionInstance(net.minecraft.sounds.SoundSource.MASTER).get());out.put("scope","real Minecraft baked models and initialized renderers; individual animated visual acceptance and gameplay NOT_RUN");var dir=Path.of("../../docs/implementation/stabilization269-20261026/client-assets");Files.createDirectories(dir);Files.writeString(dir.resolve("receipt.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));System.out.println("QA269_CLIENT_ASSETS "+out.get("status")+" items="+items+" states="+states+" entities="+entities);}catch(Exception ex){ex.printStackTrace();}mc.stop();}
}
